generator.source:
"""Random pairs for the greatest common divisor.

Each builder says how its pair was made -- two multiples of seven, two
neighbouring numbers -- rather than what the answer is. Consecutive integers
never share a factor above one, so that case is guaranteed without anything
here having to divide.
"""


def generate(rng, count):
    builders = (_shared_factor, _neighbours, _one_divides_the_other, _with_zero)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, a, b, description=""):
    return {"name": name, "stdin": "%d %d\n" % (a, b), "description": description}


def _shared_factor(rng, index):
    factor = rng.randint(2, 40)
    return _case("two multiples of %d #%d" % (factor, index),
                 factor * rng.randint(2, 50), factor * rng.randint(2, 50),
                 "Both numbers were built from the same factor, so the answer "
                 "is at least that factor -- possibly more.")


def _neighbours(rng, index):
    n = rng.randint(20, 900)
    return _case("neighbouring numbers #%d" % index, n, n + 1,
                 "Consecutive integers never share a factor above 1.")


def _one_divides_the_other(rng, index):
    smaller = rng.randint(2, 60)
    return _case("one divides the other #%d" % index,
                 smaller * rng.randint(2, 30), smaller)


def _with_zero(rng, index):
    value = rng.randint(1, 500)
    zero_first = rng.random() < 0.5
    return _case("zero on %s #%d" % ("the left" if zero_first else "the right",
                                     index),
                 0 if zero_first else value, value if zero_first else 0,
                 "The loop has to cope with a zero arriving on either side.")
